stock2=stock
future_lost=0
first_stockout=-1
for r in sorted(future, key=lambda r:(r["event_time"],r["event_id"])):
    if r["kind"]=="receipt":
        stock2 += r["quantity"]
    else:
        unmet=max(0,r["quantity"]-stock2)
        if unmet>0 and first_stockout==-1:
            first_stockout=r["event_time"]
        future_lost += unmet
        stock2 -= min(stock2,r["quantity"])
stock2, future_lost, first_stockout
